export const MONSTER_FAMILIES = Object.keys(MONSTER_ART);
export function shadeRow(family, shade) {
  const a = MONSTER_ART[family];
  const i = a ? a.shades.indexOf(shade) : -1;
  return i < 0 ? 0 : i;
}
